# (English name, Turkish name, Turkish content) - second part (novenas, litanies, examinations, Scripture passages)
# Scripture passages are free modern Turkish renderings of the King James text used in the English seed.
DATA = [
    ("Novena to The Divine Mercy", "İlahi Merhamet Novenası",
     "İlahi Merhamet Novenası, Aziz Faustina Kowalska'nın Günlüğü'ne göre Rabbimiz'in kendisi tarafından verilmiştir; Kutsal Cuma'dan başlayıp art arda dokuz gün sürmesini ve Paskalya'dan sonraki Pazar olan İlahi Merhamet Pazarı'nda sona ermesini istemiştir. Her gün İlahi Merhamet Koroncası okunur ve o güne emanet edilen ruhlar Rab'bin önüne getirilir.\n\n1. Gün — Tüm insanlık, özellikle tüm günahkârlar\n2. Gün — Rahiplerin ve dinî kişilerin ruhları\n3. Gün — Tüm dindar ve sadık ruhlar\n4. Gün — Henüz Tanrı'ya inanmayanlar ve İsa'yı henüz tanımayanlar\n5. Gün — Kilise'den ayrılmış olanların ruhları\n6. Gün — Yumuşak ve alçakgönüllü ruhlar ve küçük çocukların ruhları\n7. Gün — İlahi Merhamet'i özellikle onurlandıran ve yücelten ruhlar\n8. Gün — Araf'ta tutulan ruhlar\n9. Gün — Ilık hale gelmiş ruhlar\n\nSonsuz Baba, çok sevgili Oğlun Rabbimiz İsa Mesih'in Bedenini ve Kanını, Ruhunu ve Tanrılığını, günahlarımızın ve tüm dünyanın günahlarının kefareti olarak Sana sunuyorum."),
    ("Novena to the Holy Spirit (Prayer of Cardinal Mercier)", "Kutsal Ruh Novenası (Kardinal Mercier'in Duası)",
     "Kutsal Ruh Novenası geleneksel olarak, havarilerin ve Meryem'in Kutsal Ruh'u bekleyerek dua için toplanmasını (Elçilerin İşleri 1:14) taklit ederek, Göğe Yükseliş Perşembe'si ile Pentekost Pazarı arasındaki dokuz gün boyunca okunur. Her gün Malines Başpiskoposu Kardinal Désiré-Joseph Mercier'in yazdığı aşağıdaki dua belirli bir niyetle okunur.\n\nEy Kutsal Ruh, ışığın ve sevginin İlahi Ruhu, anlayışımı, yüreğimi ve irademi Sana adıyorum.\nBundan sonra anlayışım her zaman göksel ilhamlarına ve Senin yanılmaz Rehberi olduğun Kutsal Katolik Kilisesi'nin öğretisine itaat etsin;\nyüreğim her zaman Tanrı sevgisi ve komşu sevgisiyle tutuşsun;\nirademi her zaman İlahi İrade'ye uyum sağlasın\nve tüm yaşamım Rabbimiz ve Kurtarıcımız İsa Mesih'in yaşamının ve erdemlerinin sadık bir taklidi olsun;\nO'na, Baba ve Sen'le birlikte, sonsuza dek onur ve yücelik olsun.\nAmin.\n\n(Her günü bir Babamız, Selam Meryem ve Şan Olsun ile bitirin.)"),
    ("Litany of the Holy Name of Jesus", "İsa'nın Kutsal Adı Litanyası",
     "Rab, bize merhamet et.\nMesih, bize merhamet et.\nRab, bize merhamet et.\nİsa, bizi duy.\nİsa, lütfen bizi duy.\n\nGöksel Baba Tanrı, bize merhamet et.\nDünyanın Kurtarıcısı Oğul Tanrı, bize merhamet et.\nKutsal Ruh Tanrı, bize merhamet et.\nKutsal Teslis, tek Tanrı, bize merhamet et.\n\nİsa, yaşayan Tanrı'nın Oğlu, bize merhamet et.\nİsa, Baba'nın görkemi, bize merhamet et.\nİsa, sonsuz ışığın parıltısı, bize merhamet et.\nİsa, yücelik Kralı, bize merhamet et.\nİsa, adaletin güneşi, bize merhamet et.\nİsa, Bakire Meryem'in Oğlu, bize merhamet et.\nİsa, en sevimli, bize merhamet et.\nİsa, en hayranlık uyandıran, bize merhamet et.\nİsa, güçlü Tanrı, bize merhamet et.\nİsa, gelecek dünyanın babası, bize merhamet et.\nİsa, büyük öğüdün meleği, bize merhamet et.\nİsa, en güçlü, bize merhamet et.\nİsa, en sabırlı, bize merhamet et.\nİsa, en itaatkâr, bize merhamet et.\nİsa, yüreği yumuşak ve alçakgönüllü, bize merhamet et.\nİsa, iffet sevgilisi, bize merhamet et.\nİsa, bizi seven, bize merhamet et.\nİsa, barış Tanrısı, bize merhamet et.\nİsa, yaşamın yaratıcısı, bize merhamet et.\nİsa, erdemlerin örneği, bize merhamet et.\nİsa, ruhların gayretli sevgilisi, bize merhamet et.\nİsa, Tanrımız, bize merhamet et.\nİsa, sığınağımız, bize merhamet et.\nİsa, yoksulların babası, bize merhamet et.\nİsa, sadıkların hazinesi, bize merhamet et.\nİsa, iyi çoban, bize merhamet et.\nİsa, gerçek ışık, bize merhamet et.\nİsa, sonsuz bilgelik, bize merhamet et.\nİsa, sonsuz iyilik, bize merhamet et.\nİsa, yolumuz ve yaşamımız, bize merhamet et.\nİsa, Meleklerin sevinci, bize merhamet et.\nİsa, Patriklerin kralı, bize merhamet et.\nİsa, Havarilerin efendisi, bize merhamet et.\nİsa, Müjdecilerin öğretmeni, bize merhamet et.\nİsa, Şehitlerin gücü, bize merhamet et.\nİsa, İtirafçıların ışığı, bize merhamet et.\nİsa, Bakirelerin saflığı, bize merhamet et.\nİsa, tüm Azizlerin tacı, bize merhamet et.\n\nMerhametli ol, bizi bağışla, ey İsa.\nMerhametli ol, lütfen bizi duy, ey İsa.\n\nTüm kötülükten, bizi kurtar, ey İsa.\nTüm günahtan, bizi kurtar, ey İsa.\nÖfkenden, bizi kurtar, ey İsa.\nŞeytanın tuzaklarından, bizi kurtar, ey İsa.\nSonsuz ölümden, bizi kurtar, ey İsa.\nİlhamlarını ihmal etmekten, bizi kurtar, ey İsa.\n\nKutsal Enkarnasyon sırrınla, bizi kurtar, ey İsa.\nDoğuşunla, bizi kurtar, ey İsa.\nÇocukluğunla, bizi kurtar, ey İsa.\nEn ilahi Yaşamınla, bizi kurtar, ey İsa.\nEmeklerinle, bizi kurtar, ey İsa.\nÇilen ve Acınla, bizi kurtar, ey İsa.\nHaçın ve terk edilişinle, bizi kurtar, ey İsa.\nÖlümün ve gömülüşünle, bizi kurtar, ey İsa.\nDirilişinle, bizi kurtar, ey İsa.\nGöğe Yükselişinle, bizi kurtar, ey İsa.\nEn Kutsal Efkaristiya'yı kurmanla, bizi kurtar, ey İsa.\nSevinçlerinle, bizi kurtar, ey İsa.\nYüceliğinle, bizi kurtar, ey İsa.\n\nDünyanın günahlarını kaldıran Tanrı'nın Kuzusu, bizi bağışla, ey İsa.\nDünyanın günahlarını kaldıran Tanrı'nın Kuzusu, lütfen bizi duy, ey İsa.\nDünyanın günahlarını kaldıran Tanrı'nın Kuzusu, bize merhamet et, ey İsa.\n\nİsa, bizi duy.\nİsa, lütfen bizi duy.\n\nDua edelim.\nEy Rab İsa Mesih, 'İsteyin, size verilecek; arayın, bulacaksınız; kapıyı çalın, size açılacak' dedin: Senden isteyen bizlere en ilahi sevgi armağanını ver, Seni tüm yüreğimizle sevelim ve söz ve eylemle Seni övmekten asla vazgeçmeyelim.\nBize, ey Rab, Kutsal Adın'a karşı sürekli bir korku kadar sürekli bir sevgi ver, çünkü Sevgin'de sağlam kıldıklarını yönetmekten asla vazgeçmezsin.\nYaşayan ve sonsuza dek hüküm süren Sen.\nAmin."),
    ("General Confession (Book of Common Prayer)", "Genel İtiraf (Book of Common Prayer)",
     "Her Şeye Gücü Yeten ve en merhametli Baba;\nKaybolmuş koyunlar gibi yollarından saptık ve yanıldık.\nKendi yüreklerimizin tasarılarını ve arzularını çok fazla izledik.\nKutsal yasalarına karşı suç işledik.\nYapmamız gereken şeyleri yapmadık;\nve yapmamamız gereken şeyleri yaptık;\nve içimizde sağlık yok.\nAma Sen, ey Rab, bize, zavallı suçlulara merhamet et.\nSuçlarını itiraf edenleri esirge, ey Tanrı.\nTövbe edenleri eski haline getir;\nRabbimiz İsa Mesih'te insanlığa bildirdiğin vaatlere uygun olarak.\nVe ver, ey en merhametli Baba, onun hatırı için;\nBundan sonra tanrısal, doğru ve ölçülü bir yaşam sürelim,\nKutsal Adın'ın yüceliği için.\nAmin."),
    ("Lectio Divina — The Road to Emmaus (Luke 24:13–35)", "Lectio Divina — Emmaus Yolu (Luka 24:13–35)",
     "Lectio Divina'nın dört klasik hareketini kullanarak, Dirilmiş Mesih ile Emmaus yolunda buluşan iki öğrencinin İncil anlatısı (Luka 24:13–35) ile dua etmenin rehberli bir yolu.\n\n1. LECTIO — Oku\nLuka 24:13–35'i yavaşça, belki birden fazla kez okuyun. İki öğrenci çarmıha gerilişten sonra yas tutarak Kudüs'ten Emmaus'a yürüyor. Bir yabancı onlara katılıyor, üzüntülerini dinliyor ve Kutsal Yazılar'ı onlara açıyor, ama onu ancak sonra, ekmeğin bölünmesinde tanıyorlar.\n\n2. MEDITATIO — Düşün\nHayal gücünüzle onlarla yürüyün. Kendi hayatınızda, Rab'bin zaten yanınızda olduğunu fark etmeden cesareti kırılmış olarak nerede uzaklaştınız? Pasajdaki hangi söz, imge ya da an sizinle kalıyor?\n\n3. ORATIO — Dua et\nÖğrencilerin yapabileceği gibi Mesih'le konuşun. Kutsal Yazılar'ı onlara açtığı gibi size de açmasını ve onların sofrasında olduğu gibi ekmeğin bölünmesinde kendini size tanıtmasını isteyin.\n\n4. CONTEMPLATIO — Tefekkür et\nSözleri bir kenara bırakın ve yalnızca tanıma anında dinlenin.\n'Yolda bizimle konuşurken, bize Kutsal Yazılar'ı açarken yüreğimiz içimizde yanmıyor muydu?' — Luka 24:32\n\n5. ACTIO — Harekete geç\nHemen kalkıp haberi paylaşmak için Kudüs'e dönen öğrenciler gibi, bu karşılaşmayı sıradan gününüze taşımanın somut bir yolunu düşünün."),
    ("Examination of Conscience According to the Ten Commandments", "On Emre Göre Vicdan Muhasebesi",
     "İtiraftan önce Kutsal Ruh'tan, O'nun huzurunda yaşamınız hakkındaki gerçeği size göstermesini isteyerek, vicdanınızı emir emir sorgulayın.\n\n1. Ben Tanrın Rab'bim; Benden başka tanrıların olmayacak.\nTanrı'ya hayatımda ilk yeri verdim mi, yoksa para, başarı, rahatlık ya da başka insanları O'nun üstüne mi koydum? İmanımdan şüphe ettim ya da onu inkâr ettim mi, ya da ondan utandım mı?\n\n2. Tanrın Rab'bin adını boş yere ağzına alma.\nTanrı'nın adını dikkatsizce, öfkeyle ya da küfürle kullandım mı? Ciddi bir söz ya da yemini bozdum mu?\n\n3. Sabat gününü kutsal tutmayı hatırla.\nCiddi bir neden olmadan Pazar ya da zorunlu bir bayram Ayini'ni kaçırdım mı? Pazar'ı bir dinlenme ve ibadet günü olarak mı tuttum, yoksa yalnızca iş ve dikkat dağınıklığıyla mı doldurdum?\n\n4. Annene ve babana saygı göster.\nAnne babama ve meşru üstlerime saygılı ve itaatkâr oldum mu? Yaşlanan ya da hasta anne babama baktım mı? Bakımım altındakilere iyi örnek oldum mu?\n\n5. Öldürmeyeceksin.\nHerhangi birine bedende ya da ruhta zarar verdim mi: şiddetle, istismarla ya da ihmalle? Nefret besledim mi, kin tuttum mu ya da başkasına zarar dileğinde bulundum mu? Aşırılık ya da ihmalle kendi sağlığımı ya da hayatımı tehlikeye attım mı?\n\n6. Zina etmeyeceksin.\nÇağrıma, evli, bekâr ya da adanmış olsun, düşünce ve eylemde sadık kaldım mı? Tek başıma ya da başkasıyla saflığa karşı günah işledim mi?\n\n7. Çalmayacaksın.\nBaşkasına ait olanı aldım mı ya da elimde tuttum mu? İşimde, işlemlerimde ve yükümlülüklerimde dürüst oldum mu? Mala zarar verdim mi ya da bir borcu ödemedim mi?\n\n8. Komşuna karşı yalan tanıklık etmeyeceksin.\nYalan söyledim, dedikodu yaptım, iftira ettim ya da başkasının iyi adına zarar verdim mi? Başkalarını haksız yere yargıladım mı?\n\n9. Komşunun karısına göz dikmeyeceksin.\nBaşka biri hakkında saf olmayan düşünceler ya da arzular besledim mi ya da başkasının ilişkilerine ya da ailesine kıskançlık duydum mu?\n\n10. Komşunun malına göz dikmeyeceksin.\nBaşkalarının sahip olduklarına imrendim mi? Açgözlü, maddeci ya da Tanrı'nın bana verdiği için nankör oldum mu?\n\nRab, yaptıklarım ve yapmadıklarım için üzgünüm. Bana sağlam bir ıslah kararı ver.\n\n(Pişmanlık Duası ile devam edin.)"),
    ("The Sinner's Prayer — An Evangelical Guide to Receiving Christ", "Günahkârın Duası — Mesih'i Kabul Etmek İçin Evanjelik Bir Rehber",
     "Günahkârın Duası sabit bir litürjik metin değil, Evanjelik, Baptist ve mezhepler üstü geleneklerde birinin tövbesini ve İsa Mesih'e imanını ifade etmesi için yaygın kullanılan bir rehberdir. Genellikle kurtuluşun ABC'sinin, İtiraf et, İnan, Ağzınla Söyle etrafında şekillenir; Romalılar 3:23 ve Romalılar 10:9 gibi pasajlardan alınmıştır.\n\nA — KABUL EDİN\nTanrı'nın lütfuna ihtiyacı olan bir günahkâr olduğunuzu kabul edin.\n'Çünkü herkes günah işledi ve Tanrı'nın yüceliğinden yoksun kaldı.' — Romalılar 3:23\n\nB — İNANIN\nİsa Mesih'in günahlarınız için öldüğüne ve dirildiğine inanın ve kurtuluş için yalnız O'na güvenin.\n'Ağzınla İsa Rab'dir diye itiraf eder ve yüreğinde Tanrı'nın O'nu ölümden dirilttiğine inanırsan, kurtulursun.' — Romalılar 10:9\n\nC — İTİRAF EDİN\nİsa Mesih'e Rab ve Kurtarıcı olarak imanınızı itiraf edin, günahtan dönüp O'na yönelin.\n\nYaygın okunan bir sürüm:\n'Rab İsa, günahkâr olduğumu biliyorum ve bağışlamanı diliyorum. Günahlarım için öldüğüne ve ölümden dirildiğine inanıyorum. Günahımdan dönüyorum ve yüreğime ve hayatıma girmeni istiyorum. Seni Rabbim ve Kurtarıcım olarak izlemek ve Sana güvenmek istiyorum. Amin.'"),

    ("Psalm 8 — How Excellent Is Thy Name", "Mezmur 8 — Adın Ne Kadar Yücedir",
     "Ey Rab, Rabbimiz, adın bütün yeryüzünde ne kadar yücedir! Görkemini göklerin üstüne koydun.\nDüşmanların yüzünden, bebeklerin ve emziren çocukların ağzından kuvvet kurdun; düşmanı ve öç alanı susturmak için.\nParmaklarının işi olan göklere, ayı ve yıldızlara, yerlerine koyduğun şeylere bakınca,\nİnsan nedir ki onu anarsın? İnsanoğlu nedir ki ona ilgi gösterirsin?\nOnu meleklerden biraz aşağı yaptın, ona yücelik ve onur tacı giydirdin.\nOnu ellerinin eserleri üzerinde egemen kıldın; her şeyi ayaklarının altına koydun:\nTüm koyunları ve sığırları, evet, kır hayvanlarını,\nGöğün kuşlarını, denizin balıklarını ve deniz yollarından geçen her şeyi.\nEy Rab, Rabbimiz, adın bütün yeryüzünde ne kadar yücedir!\n\n— Mezmur 8 (serbest çeviri)"),
    ("Psalm 19 — The Heavens Declare the Glory of God", "Mezmur 19 — Gökler Tanrı'nın Yüceliğini Duyurur",
     "Gökler Tanrı'nın yüceliğini duyurur, gök kubbe elinin işini gösterir.\nGün güne söz iletir, gece geceye bilgi verir.\nSesi duyulmayan ne söz var ne dil.\nOnların çizgisi bütün yeryüzüne yayıldı, sözleri dünyanın sonuna dek. Güneş için onların içinde bir çadır kurdu,\nO, odasından çıkan bir güvey gibi, yarışa koşmak için güçlü bir adam gibi sevinir.\nÇıkışı göğün bir ucundan, dönüşü öbür ucuna kadardır; onun sıcağından saklanan hiçbir şey yoktur.\nRab'bin yasası kusursuzdur, canı tazeler; Rab'bin tanıklığı güvenilirdir, saf olanı bilge kılar.\nRab'bin buyrukları doğrudur, yüreği sevindirir; Rab'bin emri saftır, gözleri aydınlatır.\nRab korkusu temizdir, sonsuza dek kalır; Rab'bin hükümleri gerçektir ve tümüyle adildir.\nOnlar altından, evet, çok ince altından daha arzu edilir; baldan ve petek balından daha tatlıdır.\nKulun da onlarla uyarılır; onlara uymada büyük ödül vardır.\nKim kendi hatalarını anlayabilir? Beni gizli hatalardan arındır.\nKulunu küstahça günahlardan da uzak tut; üzerimde egemen olmasınlar; o zaman dürüst olurum ve büyük suçtan arınmış olurum.\nAğzımın sözleri ve yüreğimin düşüncesi gözünde kabul edilir olsun, ey Rab, kayam ve kurtarıcım.\n\n— Mezmur 19 (serbest çeviri)"),
    ("Psalm 23 — The Lord Is My Shepherd", "Mezmur 23 — Rab Çobanımdır",
     "Rab çobanımdır; eksikliğim olmaz.\nBeni yeşil otlaklarda yatırır, dingin sulara götürür.\nCanımı tazeler; adı uğruna beni doğruluk yollarında yürütür.\nÖlüm gölgesi vadisinden geçsem de kötülükten korkmam, çünkü Sen benimlesin; değneğin ve asan beni rahatlatır.\nDüşmanlarımın önünde bana bir sofra hazırlarsın; başımı yağla meshedersin; kâsem taşar.\nKuşkusuz iyilik ve merhamet ömrümün bütün günlerinde beni izleyecek ve Rab'bin evinde sonsuza dek oturacağım.\n\n— Mezmur 23 (serbest çeviri)"),
    ("Psalm 27 — The Lord Is My Light", "Mezmur 27 — Rab Benim Işığımdır",
     "Rab benim ışığım ve kurtuluşumdur; kimden korkarım? Rab yaşamımın gücüdür; kimden çekinirim?\nKötüler, düşmanlarım ve hasımlarım etimi yemek için üzerime geldiğinde, tökezleyip düştüler.\nBir ordu karşıma konaklasa da yüreğim korkmaz; savaş çıksa da buna güvenle bakarım.\nRab'den bir şey istedim, onu arayacağım: yaşamımın bütün günlerinde Rab'bin evinde oturmak, Rab'bin güzelliğine bakmak ve tapınağında araştırmak.\nÇünkü sıkıntı gününde beni çadırında saklar; çadırının gizliliğinde beni gizler; beni bir kayanın üzerine yükseltir.\nŞimdi başım çevremdeki düşmanlarımın üzerine kalkacak; bu yüzden onun çadırında sevinç kurbanları sunacağım; ezgiler söyleyeceğim, evet, Rab'be ezgiler söyleyeceğim.\nSesimle seslendiğimde duy, ey Rab; bana da merhamet et ve yanıtla beni.\n'Yüzümü arayın' dediğinde, yüreğim Sana dedi: Yüzünü, ey Rab, arayacağım.\nYüzünü benden uzak tutma; kulunu öfkeyle uzaklaştırma; yardımcım oldun; beni bırakma, terk etme, ey kurtuluşumun Tanrısı.\nBabam ve annem beni terk etse de Rab beni alır.\nBana yolunu öğret, ey Rab ve düşmanlarım yüzünden beni düz bir yolda yönet.\nBeni düşmanlarımın isteğine teslim etme; çünkü aleyhime yalancı tanıklar kalktı ve zulüm soluyanlar.\nYaşayanlar diyarında Rab'bin iyiliğini göreceğime inanmasaydım bayılmıştım.\nRab'bi bekle: cesur ol, o yüreğini güçlendirecek; bekle, diyorum, Rab'bi.\n\n— Mezmur 27 (serbest çeviri)"),
    ("Psalm 46 — God Is Our Refuge", "Mezmur 46 — Tanrı Sığınağımızdır",
     "Tanrı sığınağımız ve gücümüzdür, sıkıntıda hazır bir yardımcıdır.\nBu yüzden yeryüzü yerinden oynasa, dağlar denizin ortasına devrilse bile korkmayız;\nSuları gürleyip köpürse, dağlar kabarmasıyla titrese de. Sela.\nBir ırmak var, kolları Tanrı'nın kentini, Yüceler Yücesi'nin kutsal konutlarını sevindirir.\nTanrı onun ortasındadır; sarsılmayacak; Tanrı ona sabaha karşı yardım edecek.\nUluslar kudurdu, krallıklar sarsıldı; O sesini yükseltti, yeryüzü eridi.\nOrduların Rabbi bizimle; Yakup'un Tanrısı sığınağımızdır. Sela.\nGelin, Rab'bin işlerine bakın, yeryüzünde ne yıkımlar yaptığına.\nSavaşları yeryüzünün uçlarına dek durdurur; yayı kırar, mızrağı parçalar, arabaları ateşte yakar.\nSakin olun ve bilin ki Ben Tanrı'yım: uluslar arasında yüceltileceğim, yeryüzünde yüceltileceğim.\nOrduların Rabbi bizimle; Yakup'un Tanrısı sığınağımızdır. Sela.\n\n— Mezmur 46 (serbest çeviri)"),
    ("Psalm 51 — Have Mercy Upon Me, O God", "Mezmur 51 — Bana Merhamet Et, Ey Tanrı",
     "Bana merhamet et, ey Tanrı, sevgi dolu iyiliğine göre; şefkatinin çokluğuna göre suçlarımı sil.\nBeni suçumdan tümüyle yıka ve günahımdan arındır.\nÇünkü suçlarımı biliyorum ve günahım her zaman önümde.\nSana, yalnız Sana karşı günah işledim ve gözünde bu kötülüğü yaptım; konuştuğunda haklı çıkasın, yargıladığında temiz olasın diye.\nBak, suçlulukta şekillendim; günahta annem bana gebe kaldı.\nBak, sen içtenlikte gerçeği istersin; gizli yerde bana bilgelik öğreteceksin.\nZufa otuyla beni arındır, temiz olurum; beni yıka, kardan daha beyaz olurum.\nBeni sevinç ve neşe duymaya yönelt; kırdığın kemikler sevinsin.\nYüzünü günahlarımdan gizle ve tüm suçlarımı sil.\nBende temiz bir yürek yarat, ey Tanrı; içimde doğru bir ruh yenile.\nBeni huzurundan atma; kutsal ruhunu benden alma.\nKurtuluşunun sevincini bana geri ver; beni gönüllü bir ruhla destekle.\nO zaman suçlulara yollarını öğreteceğim ve günahkârlar Sana dönecek.\nBeni kan suçundan kurtar, ey Tanrı, kurtuluşumun Tanrısı; dilim doğruluğunu yüksek sesle söyleyecek.\nEy Rab, dudaklarımı aç; ağzım Senin övgünü duyuracak.\nÇünkü kurban istemezsin; yoksa verirdim; yakmalık sunudan hoşlanmazsın.\nTanrı'nın kurbanları kırık bir ruhtur; kırık ve ezik bir yüreği, ey Tanrı, küçümsemezsin.\nİyi niyetinle Siyon'a iyilik yap; Kudüs'ün surlarını yeniden yap.\nO zaman doğruluk kurbanlarından, yakmalık ve bütün yakmalık sunulardan hoşlanacaksın; o zaman sunağında boğalar sunacaklar.\n\n— Mezmur 51 (serbest çeviri)"),
    ("Psalm 63 — My Soul Thirsteth for Thee", "Mezmur 63 — Canım Sana Susadı",
     "Ey Tanrı, Sen benim Tanrım'sın; Seni erkenden arayacağım: canım Sana susadı, bedenim su olmayan kuru ve susuz bir diyarda Seni özlüyor;\nKutsal yerde Seni gördüğüm gibi, gücünü ve yüceliğini görmek için.\nÇünkü sevgi dolu iyiliğin yaşamdan daha iyidir; dudaklarım Seni övecek.\nBöylece yaşadığım sürece Seni kutsayacağım; Adın'da ellerimi kaldıracağım.\nCanım iliğe ve yağa doyar gibi doyacak; ağzım sevinçli dudaklarla Seni övecek:\nYatağımda Seni andığımda ve gece nöbetlerinde Seni düşündüğümde.\nÇünkü yardımcım oldun; bu yüzden kanatlarının gölgesinde sevineceğim.\nCanım Seni sıkıca izliyor; sağ elin beni destekliyor.\n\n— Mezmur 63:1-8 (serbest çeviri)"),
    ("Psalm 91 — He That Dwelleth in the Secret Place", "Mezmur 91 — Yüceler Yücesi'nin Gizli Yerinde Oturan",
     "Yüceler Yücesi'nin gizli yerinde oturan, Her Şeye Gücü Yeten'in gölgesinde kalacak.\nRab için şöyle diyeceğim: O benim sığınağım ve kalemdir; Tanrım, O'na güveneceğim.\nÇünkü seni kuş avcısının tuzağından ve ölümcül salgından kurtaracak.\nSeni tüyleriyle örtecek ve kanatlarının altında güvenceyi bulacaksın; gerçeği senin kalkanın ve siperin olacak.\nGece dehşetinden korkmayacaksın, gündüz uçan oktan da;\nKaranlıkta yürüyen salgından, öğle vakti yıkım getirenden de.\nYanında bin kişi, sağında on bin kişi düşecek; ama sana yaklaşmayacak.\nYalnızca gözlerinle bakacak ve kötülerin cezasını göreceksin.\nSığınağım olan Rab'bi, Yüceler Yücesi'ni konutun yaptığın için,\nSana hiçbir kötülük gelmeyecek, çadırına hiçbir bela yaklaşmayacak.\nÇünkü bütün yollarında seni korumaları için meleklerine emir verecek.\nSeni ellerinde taşıyacaklar, ayağın taşa çarpmasın diye.\nAslan ve engerek üzerinde yürüyeceksin; genç aslanı ve ejderi ayaklar altına alacaksın.\nBeni sevdiği için onu kurtaracağım; onu yücelteceğim, çünkü Adımı bildi.\nBana seslenecek, ben ona yanıt vereceğim; sıkıntıda onunla olacağım; onu kurtaracağım ve onurlandıracağım.\nOnu uzun ömürle doyuracağım ve ona kurtuluşumu göstereceğim.\n\n— Mezmur 91 (serbest çeviri)"),
    ("Psalm 100 — Make a Joyful Noise", "Mezmur 100 — Sevinç Çığlıkları Atın",
     "Ey bütün yeryüzü, Rab'be sevinç çığlıkları atın.\nRab'be sevinçle hizmet edin; ezgilerle huzuruna gelin.\nBilin ki Rab Tanrı'dır; bizi O yarattı, biz kendimiz değil; biz O'nun halkıyız ve otlağının koyunlarıyız.\nKapılarına şükranla, avlularına övgüyle girin; O'na şükredin ve adını kutsayın.\nÇünkü Rab iyidir; merhameti sonsuzdur; gerçeği kuşaktan kuşağa sürer.\n\n— Mezmur 100 (serbest çeviri)"),
    ("Psalm 103 — Bless the Lord, O My Soul", "Mezmur 103 — Ey Canım, Rab'bi Öv",
     "Ey canım, Rab'bi kutsa; içimdeki her şey O'nun kutsal adını kutsasın.\nEy canım, Rab'bi kutsa ve O'nun hiçbir iyiliğini unutma:\nTüm suçlarını bağışlayan; tüm hastalıklarını iyileştiren;\nYaşamını yıkımdan kurtaran; seni sevgi dolu iyilik ve şefkatle taçlandıran;\nAğzını iyi şeylerle doyuran; öyle ki gençliğin kartalınki gibi yenilenir.\nRab ezilen herkes için doğruluk ve adalet yapar.\nYollarını Musa'ya, işlerini İsrail oğullarına bildirdi.\nRab merhametli ve lütufkârdır, öfkeye yavaş ve merhamette bol.\nHer zaman azarlamaz, öfkesini sonsuza dek tutmaz.\nBize günahlarımıza göre davranmadı, suçlarımıza göre karşılık vermedi.\nÇünkü gök yerin üstünde ne kadar yüksekse, kendisinden korkanlara merhameti o kadar büyüktür.\nDoğu batıdan ne kadar uzaksa, suçlarımızı bizden o kadar uzak tuttu.\nBir baba çocuklarına nasıl acırsa, Rab de kendisinden korkanlara öyle acır.\n\n— Mezmur 103:1-13 (serbest çeviri)"),
    ("Psalm 121 — I Will Lift Up Mine Eyes", "Mezmur 121 — Gözlerimi Dağlara Kaldırıyorum",
     "Gözlerimi dağlara kaldırıyorum; yardım nereden gelecek?\nYardımım göğü ve yeri yaratan Rab'den gelir.\nAyağının kaymasına izin vermez; seni koruyan uyuklamaz.\nBak, İsrail'i koruyan ne uyuklar ne uyur.\nRab senin koruyucundur; Rab sağ yanında gölgendir.\nGündüz güneş sana vurmaz, gece de ay.\nRab seni her kötülükten koruyacak; canını koruyacak.\nRab çıkışını ve girişini, şimdiden ve sonsuza dek koruyacak.\n\n— Mezmur 121 (serbest çeviri)"),
    ("Psalm 139 — O Lord, Thou Hast Searched Me", "Mezmur 139 — Ey Rab, Beni Araştırdın",
     "Ey Rab, beni araştırdın ve tanıdın.\nOturuşumu ve kalkışımı biliyorsun; düşüncemi uzaktan anlıyorsun.\nYolumu ve yatışımı kuşatıyorsun ve tüm yollarımı biliyorsun.\nÇünkü dilimde bir söz olmadan, bak, ey Rab, hepsini biliyorsun.\nBeni arkadan ve önden kuşattın ve elini üzerime koydun.\nBöyle bir bilgi benim için fazla harika; yüksek, ona erişemem.\nRuhundan nereye gideyim? Huzurundan nereye kaçayım?\nGöğe çıksam, Sen oradasın; ölüler diyarında yatağımı yapsam, bak, Sen oradasın.\nSabahın kanatlarını alsam ve denizin en uç yerlerinde otursam;\nOrada bile elin beni yönlendirir ve sağ elin beni tutar.\n'Kuşkusuz karanlık beni örter' desem; gece bile çevremde ışık olur.\nEvet, karanlık Senden gizlemez; gece gündüz gibi parlar: karanlık ve ışık Sana aynıdır.\nÇünkü iç organlarımı Sen yarattın; beni annemin karnında örttün.\nSeni öveceğim; çünkü korkunç ve harika biçimde yaratıldım: eserlerin harika; ruhum bunu çok iyi bilir.\nGizlice yapıldığımda, yerin en alt kısımlarında özenle işlendiğimde, özüm Senden gizli değildi.\nGözlerin henüz bitmemiş halimi gördü; kitabında tüm üyelerim yazılıydı, henüz hiçbiri yokken şekillendirildi.\nDüşüncelerin benim için ne kadar değerli, ey Tanrı! Toplamları ne büyük!\nOnları saysam, kumdan çoktur; uyandığımda hâlâ Seninleyim.\nKuşkusuz kötüleri öldüreceksin, ey Tanrı; ey kan dökenler, benden uzaklaşın.\nÇünkü Seni kötülükle konuşurlar ve düşmanların adını boş yere ağzına alır.\nSana nefret edenlerden nefret etmiyor muyum, ey Rab? Sana karşı kalkanlara üzülmüyor muyum?\nOnlardan mükemmel nefretle nefret ediyorum; onları düşmanlarım sayıyorum.\nBeni araştır, ey Tanrı, yüreğimi bil; beni dene, düşüncelerimi bil:\nVe bende kötü bir yol var mı gör ve beni sonsuz yolda yönlendir.\n\n— Mezmur 139 (serbest çeviri)"),
    ("Psalm 150 — Praise Ye the Lord", "Mezmur 150 — Rab'bi Övün",
     "Rab'bi övün. Tanrı'yı kutsal yerinde övün; O'nu güçlü gök kubbesinde övün.\nO'nu güçlü işleri için övün; O'nu eşsiz büyüklüğüne göre övün.\nO'nu boru sesiyle övün; O'nu lavta ve lirle övün.\nO'nu def ve dansla övün; O'nu telli çalgılar ve orglarla övün.\nO'nu yüksek zillerle övün; O'nu çınlayan zillerle övün.\nSoluk alan her şey Rab'bi övsün. Rab'bi övün.\n\n— Mezmur 150 (serbest çeviri)"),
    ("The Beatitudes", "Dağ Vaazı'ndaki Mutluluklar",
     "Ruhça yoksullar ne mutlu, çünkü göklerin egemenliği onlarındır.\nYas tutanlar ne mutlu, çünkü onlar teselli edilecek.\nYumuşak huylular ne mutlu, çünkü onlar yeryüzünü miras alacak.\nDoğruluğa acıkıp susayanlar ne mutlu, çünkü onlar doyurulacak.\nMerhametliler ne mutlu, çünkü onlar merhamet görecek.\nYüreği temiz olanlar ne mutlu, çünkü onlar Tanrı'yı görecek.\nBarışı sağlayanlar ne mutlu, çünkü onlara Tanrı'nın çocukları denilecek.\nDoğruluk uğruna zulüm görenler ne mutlu, çünkü göklerin egemenliği onlarındır.\nBenim uğruma size sövüp zulmettikleri ve yalan yere aleyhinizde her türlü kötü söz söyledikleri zaman ne mutlusunuz.\nSevinin ve çok coşun; çünkü gökte ödülünüz büyüktür; zira sizden önceki peygamberlere de böyle zulmettiler.\n\n— Matta 5:3-12 (serbest çeviri)"),
    ("The Lord's Prayer (with the Doxology)", "Rab'bin Duası (Doksoloji ile)",
     "Göklerdeki Babamız, adın kutsal kılınsın.\nEgemenliğin gelsin. İraden gökte olduğu gibi yerde de olsun.\nGündelik ekmeğimizi bugün bize ver.\nBize borçlu olanları bağışladığımız gibi, bizim borçlarımızı da bağışla.\nVe bizi ayartmaya sokma, ama kötü olandan kurtar. Çünkü egemenlik, güç ve yücelik sonsuza dek Senindir. Amin.\n\n— Matta 6:9-13 (serbest çeviri)"),
    ("The Love Chapter (1 Corinthians 13)", "Sevgi Bölümü (1. Korintliler 13)",
     "İnsanların ve meleklerin dilleriyle konuşsam da sevgim yoksa, ses çıkaran bir bakır ya da çınlayan bir zil gibi oldum.\nPeygamberlik armağanım olsa, tüm sırları ve tüm bilgiyi anlasam, dağları yerinden oynatacak tüm imanım olsa da sevgim yoksa, hiçbir şeyim.\nTüm mallarımı yoksulları doyurmak için versem ve bedenimi yakılmak için teslim etsem de sevgim yoksa, bana hiçbir yararı yoktur.\nSevgi sabırlıdır, iyiliksever; sevgi kıskanmaz; övünmez, şişinmez,\nKaba davranmaz, kendi çıkarını aramaz, kolay öfkelenmez, kötülük düşünmez;\nHaksızlığa sevinmez, gerçeğe sevinir;\nHer şeye katlanır, her şeye inanır, her şeyi umar, her şeye dayanır.\nSevgi asla son bulmaz: peygamberlikler varsa ortadan kalkacak; diller varsa duracak; bilgi varsa yok olacak.\nÇünkü kısmen biliriz ve kısmen peygamberlik ederiz.\nAma kusursuz olan gelince, kısmi olan ortadan kalkacak.\nÇocukken çocuk gibi konuştum, çocuk gibi anladım, çocuk gibi düşündüm; ama adam olunca çocukça şeyleri bıraktım.\nŞimdi bir aynada belirsiz görüyoruz; ama o zaman yüz yüze: şimdi kısmen biliyorum; ama o zaman tanındığım gibi tanıyacağım.\nŞimdi iman, umut, sevgi, bu üçü kalıyor; ama bunların en büyüğü sevgidir.\n\n— 1. Korintliler 13 (serbest çeviri)"),
    ("Nothing Can Separate Us (Romans 8:31-39)", "Hiçbir Şey Bizi Ayıramaz (Romalılar 8:31-39)",
     "O halde bunlara ne diyeceğiz? Tanrı bizden yanaysa, kim bize karşı olabilir?\nKendi Oğlu'nu esirgemeyip hepimiz için teslim eden, O'nunla birlikte bize her şeyi de lütfetmez mi?\nTanrı'nın seçtiklerini kim suçlayabilir? Aklayan Tanrı'dır.\nKim mahkûm edebilir? Ölen, hatta dirilen, Tanrı'nın sağında olan ve bizim için aracılık eden Mesih'tir.\nBizi Mesih'in sevgisinden kim ayıracak? Sıkıntı mı, ezgi mi, zulüm mü, kıtlık mı, çıplaklık mı, tehlike mi, kılıç mı?\nYazıldığı gibi: 'Senin uğruna bütün gün öldürülüyoruz; kesilecek koyunlar gibi sayıldık.'\nHayır, tüm bunlarda bizi sevenin aracılığıyla galiplerden daha üstünüz.\nÇünkü ikna oldum ki ne ölüm, ne yaşam, ne melekler, ne yönetimler, ne güçler, ne şimdiki şeyler, ne gelecek şeyler,\nNe yükseklik, ne derinlik, ne de başka herhangi bir yaratık, bizi Rabbimiz Mesih İsa'daki Tanrı sevgisinden ayıramayacak.\n\n— Romalılar 8:31-39 (serbest çeviri)"),
    ("The Word Became Flesh (John 1:1-14)", "Söz Beden Oldu (Yuhanna 1:1-14)",
     "Başlangıçta Söz vardı, Söz Tanrı'yla birlikteydi ve Söz Tanrı'ydı.\nO başlangıçta Tanrı'yla birlikteydi.\nHer şey O'nun aracılığıyla var oldu; var olan hiçbir şey O'nsuz var olmadı.\nO'nda yaşam vardı ve yaşam insanların ışığıydı.\nIşık karanlıkta parlar ve karanlık onu kavramadı.\nTanrı tarafından gönderilmiş bir adam vardı, adı Yahya'ydı.\nO tanıklık için geldi, Işık'a tanıklık etsin ki herkes onun aracılığıyla inansın.\nO o Işık değildi, ama o Işık'a tanıklık etmek için gönderildi.\nGerçek Işık, dünyaya gelen her insanı aydınlatandı.\nO dünyadaydı ve dünya O'nun aracılığıyla var oldu, ama dünya O'nu tanımadı.\nKendi evine geldi, ama kendi halkı O'nu kabul etmedi.\nAma O'nu kabul eden, adına iman eden herkese Tanrı'nın çocukları olma hakkını verdi:\nKan'dan, beden isteğinden, insan isteğinden değil, Tanrı'dan doğanlara.\nVe Söz beden oldu ve aramızda yaşadı (ve O'nun yüceliğini, Baba'nın biricik Oğlu'nun yüceliği gibi gördük), lütuf ve gerçekle doluydu.\n\n— Yuhanna 1:1-14 (serbest çeviri)"),
    ("Let Not Your Heart Be Troubled (John 14:1-6)", "Yüreğiniz Sıkılmasın (Yuhanna 14:1-6)",
     "Yüreğiniz sıkılmasın: Tanrı'ya inanıyorsunuz, bana da inanın.\nBabamın evinde birçok konut var; yoksa size söylerdim. Size yer hazırlamaya gidiyorum.\nGidip size yer hazırlarsam, yine gelip sizi yanıma alacağım; ben nerede isem siz de orada olasınız.\nNereye gittiğimi ve yolu biliyorsunuz.\nTomas O'na dedi: Rab, nereye gittiğini bilmiyoruz; yolu nasıl bilebiliriz?\nİsa ona dedi: Yol, gerçek ve yaşam Ben'im; Baba'ya Benim aracılığım olmadan kimse gelemez.\n\n— Yuhanna 14:1-6 (serbest çeviri)"),
    ("Rejoice in the Lord Always (Philippians 4:4-9)", "Rab'de Her Zaman Sevinin (Filipililer 4:4-9)",
     "Rab'de her zaman sevinin; yine diyorum: sevinin.\nYumuşak başlılığınız tüm insanlarca bilinsin. Rab yakındır.\nHiçbir şey için kaygılanmayın; ama her konuda dua ve yakarışla, şükranla isteklerinizi Tanrı'ya bildirin.\nVe her anlayışı aşan Tanrı'nın esenliği, yüreklerinizi ve düşüncelerinizi Mesih İsa'da koruyacak.\nSon olarak, kardeşler, neler gerçekse, neler onurluysa, neler doğruysa, neler saf, neler sevimli, neler iyi bir ün taşıyorsa; bir erdem ve övgüye değer bir şey varsa, bunları düşünün.\nBenden öğrendiğiniz, aldığınız, duyduğunuz ve gördüğünüz şeyleri yapın; esenlik Tanrısı sizinle olacak.\n\n— Filipililer 4:4-9 (serbest çeviri)"),
    ("They That Wait Upon the Lord (Isaiah 40:28-31)", "Rab'bi Bekleyenler (Yeşaya 40:28-31)",
     "Bilmedin mi? Duymadın mı ki sonsuz Tanrı, yeryüzünün uçlarının Yaratıcısı Rab, yorulmaz ve bitkin düşmez? O'nun anlayışı araştırılamaz.\nYorgunlara güç verir; gücü olmayanın kuvvetini artırır.\nGençler bile yorulur ve bitkin düşer, delikanlılar kesinlikle düşer:\nAma Rab'bi bekleyenler güçlerini yenileyecekler; kartallar gibi kanatlarla yükselecekler; koşacaklar ve yorulmayacaklar; yürüyecekler ve bitkin düşmeyecekler.\n\n— Yeşaya 40:28-31 (serbest çeviri)"),
    ("Fear Thou Not (Isaiah 41:10)", "Korkma (Yeşaya 41:10)",
     "Korkma, çünkü ben seninleyim; yılma, çünkü ben senin Tanrın'ım: seni güçlendireceğim; evet, sana yardım edeceğim; evet, seni doğruluğumun sağ eliyle destekleyeceğim.\n\n— Yeşaya 41:10 (serbest çeviri)"),
    ("Trust in the Lord (Proverbs 3:5-6)", "Rab'be Güven (Süleyman'ın Özdeyişleri 3:5-6)",
     "Tüm yüreğinle Rab'be güven; kendi anlayışına yaslanma.\nTüm yollarında O'nu an, O senin yollarını yönlendirecek.\n\n— Süleyman'ın Özdeyişleri 3:5-6 (serbest çeviri)"),
    ("Be Strong and of a Good Courage (Joshua 1:9)", "Güçlü ve Cesur Ol (Yeşu 1:9)",
     "Sana buyurmadım mı? Güçlü ve cesur ol; korkma ve yılma: çünkü nereye gidersen git Tanrın Rab seninledir.\n\n— Yeşu 1:9 (serbest çeviri)"),
    ("What Doth the Lord Require (Micah 6:8)", "Rab Senden Ne İster (Mika 6:8)",
     "Ey insan, sana neyin iyi olduğunu gösterdi; Rab senden adil davranmaktan, merhameti sevmekten ve Tanrın'la alçakgönüllülükle yürümekten başka ne ister?\n\n— Mika 6:8 (serbest çeviri)"),
    ("The Magnificat (Luke 1:46-55)", "Magnificat (Luka 1:46-55)",
     "Ve Meryem dedi: Canım Rab'bi yüceltir,\nVe ruhum Kurtarıcım Tanrı'da sevindi.\nÇünkü O kulunun alçak durumuna baktı: işte, bundan böyle bütün kuşaklar bana mutlu diyecek.\nÇünkü Güçlü Olan benim için büyük şeyler yaptı; ve adı kutsaldır.\nVe merhameti, O'ndan korkanlara kuşaktan kuşağa sürer.\nKolunun gücünü gösterdi; kendi yüreklerinin düşüncesinde kibirlileri dağıttı.\nGüçlüleri tahtlarından indirdi ve alçakları yükseltti.\nAçları iyi şeylerle doyurdu; zenginleri ise eli boş gönderdi.\nMerhametini anarak kulu İsrail'e yardım etti;\nAtalarımıza, İbrahim'e ve soyuna sonsuza dek söylediği gibi.\n\n— Luka 1:46-55 (serbest çeviri)"),
    ("The Benedictus (Luke 1:68-79)", "Benedictus (Luka 1:68-79)",
     "İsrail'in Tanrısı Rab kutsanmış olsun; çünkü halkını ziyaret etti ve kurtardı,\nVe kulu Davut'un evinde bizim için bir kurtuluş borusu yükseltti;\nDünyanın başlangıcından beri olan kutsal peygamberlerinin ağzıyla söylediği gibi:\nDüşmanlarımızdan ve bizden nefret eden herkesin elinden kurtulacağımızı;\nAtalarımıza vaat edilen merhameti yerine getirmeyi ve kutsal antlaşmasını anmayı;\nAtamız İbrahim'e ettiği yemini,\nBize vereceğini ki düşmanlarımızın elinden kurtulup\nÖmrümüzün bütün günlerinde önünde kutsallık ve doğrulukla korkusuzca O'na hizmet edelim.\nVe sen, çocuk, Yüceler Yücesi'nin peygamberi olarak çağrılacaksın; çünkü Rab'bin önüne giderek yollarını hazırlayacaksın;\nHalkına günahlarının bağışlanmasıyla kurtuluş bilgisini vermek için,\nTanrımız'ın şefkatli merhameti sayesinde; yüksekten doğan şafak bizi ziyaret etti,\nKaranlıkta ve ölüm gölgesinde oturanlara ışık vermek, ayaklarımızı barış yoluna yöneltmek için.\n\n— Luka 1:68-79 (serbest çeviri)"),
    ("The Nunc Dimittis (Luke 2:29-32)", "Nunc Dimittis (Luka 2:29-32)",
     "Rab, şimdi kulunu sözüne göre esenlikle gönderiyorsun:\nÇünkü gözlerim kurtuluşunu gördü,\nTüm halkların önünde hazırladığın,\nUluslara aydınlatıcı bir ışık ve halkın İsrail'in yüceliği.\n\n— Luka 2:29-32 (serbest çeviri)"),
    ("Rooted and Grounded in Love (Ephesians 3:14-21)", "Sevgiye Kök Salmış ve Temellenmiş (Efesliler 3:14-21)",
     "Bu nedenle Rabbimiz İsa Mesih'in Babası'nın önünde diz çökerim,\nGökte ve yerde bütün ailenin adını aldığı O'nun,\nYüceliğinin zenginliğine göre Ruhu'yla iç insanda güçle güçlenmenizi,\nMesih'in imanla yüreklerinizde yaşamasını; sevgide köklenmiş ve temellenmiş olarak,\nTüm kutsallarla birlikte genişliğin, uzunluğun, derinliğin ve yüksekliğin ne olduğunu kavramaya güç bulmanızı;\nVe bilgiyi aşan Mesih'in sevgisini bilmenizi ki Tanrı'nın tüm doluluğuyla dolasınız.\nŞimdi bizde etkin olan güce göre, istediğimizden ya da düşündüğümüzden çok daha fazlasını yapabilen O'na,\nKilise'de Mesih İsa aracılığıyla tüm çağlar boyunca, çağların sonuna dek yücelik olsun. Amin.\n\n— Efesliler 3:14-21 (serbest çeviri)"),
    ("Put On Love (Colossians 3:12-17)", "Sevgiyi Kuşanın (Koloseliler 3:12-17)",
     "Bu nedenle, Tanrı'nın seçilmişleri, kutsal ve sevilen olarak, merhamet duygularını, iyiliği, alçakgönüllülüğü, yumuşak huyluluğu, sabrı kuşanın;\nBirbirinize katlanın ve birinin diğerine karşı bir şikâyeti varsa birbirinizi bağışlayın: Mesih sizi nasıl bağışladıysa siz de öyle yapın.\nBütün bunların üstüne, olgunluğun bağı olan sevgiyi kuşanın.\nVe Tanrı'nın esenliği yüreklerinizde hüküm sürsün; buna tek bedende çağrıldınız; ve şükredin.\nMesih'in sözü içinizde bolca, tüm bilgelikle yaşasın; mezmurlarla, ilahilerle ve ruhsal şarkılarla birbirinizi öğretip uyarın, yüreklerinizde lütufla Rab'be şarkı söyleyin.\nVe ne yaparsanız, söz ya da eylemle, hepsini Rab İsa'nın adıyla yapın, O'nun aracılığıyla Tanrı'ya ve Baba'ya şükrederek.\n\n— Koloseliler 3:12-17 (serbest çeviri)"),
    ("Benedictus (Canticle of Zechariah)", "Benedictus (Zekeriya'nın İlahisi)",
     "İsrail'in Tanrısı Rab kutsanmış olsun,\nçünkü halkını ziyaret etti ve kurtardı;\nve kulu Davut'un evinde bizim için güçlü bir kurtuluş yükseltti,\nDünyanın başlangıcından beri olan\nkutsal peygamberlerinin ağzıyla söylediği gibi;\nDüşmanlarımızdan\nve bizden nefret edenlerin elinden kurtulacağımızı;\nAtalarımıza vaat edilen merhameti yerine getirmeyi\nve kutsal antlaşmasını anmayı;\nAtamız İbrahim'e ettiği yemini yerine getirmeyi,\nbize vereceğine dair;\nÖyle ki düşmanlarımızın elinden kurtulmuş olarak,\nkorkusuzca O'na hizmet edelim,\nÖmrümüzün bütün günlerinde\nönünde kutsallık ve doğrulukla.\nVe sen, çocuk, Yüceler Yücesi'nin peygamberi diye çağrılacaksın,\nçünkü Rab'bin önüne giderek yollarını hazırlayacaksın;\nHalkına kurtuluş bilgisini vermek için,\nGünahlarının bağışlanması için,\nTanrımız'ın şefkatli merhameti sayesinde,\nyüksekten doğan şafak bizi ziyaret etti;\nKaranlıkta ve ölüm gölgesinde oturanlara ışık vermek,\nve ayaklarımızı barış yoluna yöneltmek için.\nBaba'ya, Oğul'a ve Kutsal Ruh'a şan olsun,\nbaşlangıçta olduğu gibi, şimdi ve her zaman,\nçağların sonuna dek.\nAmin.\n\n(Benedictus olarak bilinen bu, Luka 1:68-79'dan Zekeriya'nın İlahisi'dir; oğlu Vaftizci Yahya'nın doğumundaki övgü ilahisidir. Magnificat ve Nunc Dimittis ile birlikte, Katolik, Ortodoks ve Anglikan geleneklerinde Saatler Litürjisi'nde günlük, geleneksel olarak Lauds ya da Sabah Duası'nda okunan üç Yeni Antlaşma İncil ilahisinden biridir.)"),
    ("Cherubic Hymn (Cherubikon) — Byzantine Divine Liturgy", "Kerubik İlahi (Cherubikon) — Bizans İlahi Litürjisi",
     "Gizemli biçimde Kerubiler'i temsil eden\nve Yaşam Veren Teslis'e üç kez kutsal ilahisini söyleyen bizler,\nşimdi tüm dünyevi kaygıları bırakalım,\nöyle ki tüm Kral'ı karşılayalım,\nmelek orduları tarafından görünmez biçimde eşlik edilen.\nAleluya, aleluya, aleluya.\n\n(Bizans Ayini'nin Aziz Yuhanna Chrysostomos İlahi Litürjisi'nin Büyük Giriş'inde, din adamları ekmeği ve şarabı hazırlık masasından sunağa geçit töreniyle taşırken koro tarafından söylenir.)"),
    ("Collect for Aid against Perils (Book of Common Prayer)", "Tehlikelere Karşı Yardım Toplama Duası (Book of Common Prayer)",
     "Karanlığımızı aydınlat, sana yalvarırız, ey Rab;\nve büyük merhametinle bizi bu gecenin tüm tehlikelerinden ve belalarından koru;\nbiricik Oğlun, Kurtarıcımız İsa Mesih'in sevgisi için.\nAmin."),
]
